function stripColorings(n: number): number {
  const M = 1_000_000_007;
  const rows: number[][] = [];
  for (let a = 0; a < 3; a++)
    for (let b = 0; b < 3; b++)
      for (let c = 0; c < 3; c++)
        if (a !== b && b !== c) rows.push([a, b, c]);
  let ways = rows.map(() => 1);
  for (let k = 1; k < n; k++) {
    const next = rows.map(() => 0);
    for (let i = 0; i < rows.length; i++)
      for (let j = 0; j < rows.length; j++) {
        const [p, q] = [rows[i], rows[j]];
        if (p[0] !== q[0] && p[1] !== q[1] && p[2] !== q[2]) next[j] = (next[j] + ways[i]) % M;
      }
    ways = next;
  }
  return ways.reduce((s, w) => (s + w) % M, 0);
}

