class Solution:
    def stripColorings(self, n: int) -> int:
        M = 1_000_000_007
        rows = [(a, b, c) for a in range(3) for b in range(3) for c in range(3) if a != b and b != c]
        fits = [[j for j, q in enumerate(rows) if all(x != y for x, y in zip(p, q))] for p in rows]
        ways = [1] * len(rows)
        for _ in range(n - 1):
            nxt = [0] * len(rows)
            for i, w in enumerate(ways):
                for j in fits[i]:
                    nxt[j] = (nxt[j] + w) % M
            ways = nxt
        return sum(ways) % M

